/* NOEASY · The Halls · presence.js — other visitors walk the hall as ghosts.

   Nobody registers. When a visitor presses ENTER, the page opens a WebSocket to the Mindgate bot
   (api/halls.py, address from assets/door.js) and from then on sends where it stands and where it
   looks, ten times a second at most and only when that changed. The bot answers with everyone else.

   WHAT A VISITOR SEES
   · Everyone else, as the same hooded figure (a cloak draped in Blender, cut down to ~2 600 facets),
     drawn as an ordered dither: each facet lit flat in four steps, then only some of its pixels kept.
     80 % of the figure is see-through (OPACITY 0.2). Nothing is blended, so figures need no sorting
     and pass through each other; each guest's dither is offset differently, so two overlapping
     guests interleave their dots instead of covering each other.
   · A colour per guest from PALETTE, handed out by the server: all different while the hall holds
     six people or fewer, then repeating.
   · The country (from the IP, on the server) as plain text over the head; nothing if unknown.
   · Never itself: the server tells the page its own id and the page skips it.
   · No sound from others at all: this file plays nothing; steps and clicks stay local.

   HOW IT FITS THE HALL
   · The main loop calls window.__presence(dt, groundY, yaw) once a frame before rendering:
     groundY is the eye height minus EYE, so stairs, the pit and the balcony carry over.
   · The figure's colours are written as they are (no tone mapping), with the hall's fog
     approximated in the shader: far guests fade into the warm haze and thin out.
   · Paintings are picked by their own raycast list, so a guest never blocks a click.

   Test hook: window.__hallsLive = 'ws://…' before this file loads points it at a local server. */
(function () {
  'use strict';
  var THREE = window.THREE;
  if (!THREE || new URLSearchParams(location.search).get('view')) return;   // ?view= is the screenshot mode

  var PALETTE = ['#9b9c9c', '#98985f', '#d89b74', '#cc373f', '#a86a40', '#5d5c4b'];
  var OPACITY = 0.2;                        // 80 % transparent
  var SHIFTS = [[0, 0], [2, 1], [1, 3], [3, 2], [1, 0], [3, 3], [0, 2], [2, 3]];
  var SEND_EVERY = 100, IDLE_SEND = 4000;   // ms
  var STEP_LEN = 1.10;                      // the hall's own stride, so steps and sway match the local walker
  var MESH = {"lo":[-0.45077,0.00857,-0.19552],"hi":[0.41097,1.82609,0.35797],"n":1416,"pos":"","ao":"","idx":""};

  /* ---------- the figure ---------- */
  function b64(s, Type) {
    var bin = atob(s), u8 = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
    return new Type(u8.buffer);
  }
  var geo = new THREE.BufferGeometry();
  (function () {
    var q = b64(MESH.pos, Uint16Array), p = new Float32Array(q.length);
    for (var i = 0; i < q.length; i++) { var a = i % 3; p[i] = MESH.lo[a] + q[i] / 65535 * (MESH.hi[a] - MESH.lo[a]); }
    geo.setAttribute('position', new THREE.BufferAttribute(p, 3));
    geo.setAttribute('ao', new THREE.BufferAttribute(b64(MESH.ao, Uint8Array), 1, true));
    geo.setIndex(new THREE.BufferAttribute(b64(MESH.idx, Uint16Array), 1));
    geo.computeBoundingSphere();
    geo.boundingSphere.radius += 0.15;      // the walk bends the hem a little past the drape
  })();
  var EGG = new THREE.SphereGeometry(1, 16, 12);

  var U = { time: { value: 0 }, opacity: { value: OPACITY }, cell: { value: 2 },
    key: { value: new THREE.Vector3(-0.7, 0.6, 0.25).normalize() }, keyCol: { value: new THREE.Vector3(1.0, 0.86, 0.68) },
    fogCol: { value: new THREE.Vector3(0.184, 0.129, 0.075) }, fogD: { value: 0.028 } };
  var MOVE = [
    'uniform float uTime;uniform float uGait;uniform float uPhase;',
    'vec3 move(vec3 p){',
    ' float y=p.y;float ang=atan(p.x,p.z);vec2 d=normalize(p.xz+vec2(0.00001));',
    ' float sL=max(0.0,sin(uPhase)),sR=max(0.0,-sin(uPhase));',
    ' float knee=smoothstep(0.1,0.48,y)*(1.0-smoothstep(0.48,0.98,y));',
    ' float wl=exp(-pow((ang-0.45)/0.6,2.0)),wr=exp(-pow((ang+0.45)/0.6,2.0));',
    ' p.xz+=d*(wl*sL+wr*sR)*knee*0.045*uGait;',
    ' float low=1.0-smoothstep(0.0,1.2,y);',
    ' p.z-=uGait*low*low*0.06;p.x+=uGait*low*0.014*sin(uPhase);',
    ' float lag=1.0-smoothstep(0.2,1.45,y);',
    ' p.xz+=d*uGait*lag*lag*0.018*(0.6+0.4*sin(2.0*uPhase+ang));',
    ' p.x+=sin(uTime*0.9+y*1.3)*0.004*lag;p.z+=sin(uTime*0.7+y*1.7+1.0)*0.003*lag;',
    ' return p;',
    '}'].join('\n');
  var DITHER = [
    'uniform float uOpacity;uniform float uFade;uniform float uCell;uniform vec2 uShift;uniform vec3 uFogCol;uniform float uFogD;',
    'float b2(vec2 a){a=floor(a);return fract(a.x*0.5+a.y*a.y*0.75);}',
    'float bayer(vec2 a){return b2(0.25*a)*0.0625+b2(0.5*a)*0.25+b2(a);}',
    'float fogOf(vec3 w){float d=length(w-cameraPosition);return 1.0-exp(-uFogD*uFogD*d*d);}'].join('\n');
  var GHOST_VS = [MOVE, 'attribute float ao;varying vec3 vW;varying float vAO;',
    'void main(){vec4 wp=modelMatrix*vec4(move(position),1.0);vW=wp.xyz;vAO=ao;gl_Position=projectionMatrix*viewMatrix*wp;}'].join('\n');
  var GHOST_FS = [DITHER, 'uniform vec3 uColor;uniform vec3 uKey;uniform vec3 uKeyCol;varying vec3 vW;varying float vAO;',
    'void main(){',
    ' vec3 N=normalize(cross(dFdx(vW),dFdy(vW)));vec3 V=normalize(cameraPosition-vW);',
    ' if(dot(N,V)<0.0)N=-N;',
    ' float lit=floor(clamp(dot(N,uKey)*0.5+0.5,0.0,1.0)*4.0+0.5)/4.0;',
    ' float nv=clamp(dot(N,V),0.0,1.0);float ao=clamp(vAO,0.0,1.0);',
    ' float dens=mix(0.4,1.0,lit)*mix(0.55,1.0,ao);',
    ' dens=max(dens,pow(1.0-nv,2.0)*0.95*ao);',
    ' float fog=fogOf(vW);',
    ' dens*=(1.0-0.55*fog)*uFade;',
    ' if(dens*uOpacity<=bayer(floor(gl_FragCoord.xy/uCell)+uShift)+0.004)discard;',
    ' vec3 col=uColor*mix(0.66,1.12,lit)*mix(0.55,1.0,ao)+uKeyCol*0.04*lit;',
    ' gl_FragColor=vec4(mix(col,uFogCol,fog*0.8),1.0);',
    '}'].join('\n');
  /* the dark inside of the hood: an egg where the head would be, dithered the same way */
  var EGG_VS = 'varying vec3 vW;void main(){vec4 wp=modelMatrix*vec4(position,1.0);vW=wp.xyz;gl_Position=projectionMatrix*viewMatrix*wp;}';
  var EGG_FS = [DITHER, 'varying vec3 vW;',
    'void main(){float fog=fogOf(vW);',
    ' if(min(1.0,uOpacity*1.6)*uFade*(1.0-0.55*fog)<=bayer(floor(gl_FragCoord.xy/uCell)+uShift)+0.004)discard;',
    ' gl_FragColor=vec4(mix(vec3(0.03,0.022,0.016),uFogCol,fog*0.8),1.0);}'].join('\n');
  function noPick() {}

  var NAMES = null;
  try { NAMES = new Intl.DisplayNames(['en'], { type: 'region' }); } catch (e) {}
  function countryName(cc) {
    if (!/^[A-Z]{2}$/.test(cc || '')) return '';
    var n = '';
    try { n = NAMES ? NAMES.of(cc) : ''; } catch (e) {}
    return String(n || cc).toUpperCase();
  }
  /* the label is DotGothic16 at twice its 16 px grid, shown at exactly half size every frame (LABEL_PX
     screen pixels tall at any distance) with nearest sampling, so its pixels stay as crisp as the site's */
  var LABEL_PX = 32;
  function labelTexture(text) {
    var c = document.createElement('canvas'), g = c.getContext('2d'), font = '32px "DotGothic16", monospace';
    g.font = font; if ('letterSpacing' in g) g.letterSpacing = '2px';
    var w = Math.ceil(g.measureText(text).width) + 28;
    c.width = w + (w % 2); c.height = 64;
    g = c.getContext('2d'); g.font = font; if ('letterSpacing' in g) g.letterSpacing = '2px';
    g.textAlign = 'center'; g.textBaseline = 'middle';
    g.lineJoin = 'miter'; g.lineWidth = 6; g.strokeStyle = 'rgba(10,7,5,0.85)'; g.strokeText(text, c.width / 2, 33);
    g.fillStyle = '#e8e0c4'; g.fillText(text, c.width / 2, 33);
    var t = new THREE.CanvasTexture(c); t.encoding = THREE.sRGBEncoding;
    t.magFilter = t.minFilter = THREE.NearestFilter; t.generateMipmaps = false;
    t.noeasyAspect = c.width / c.height;          // r128 textures have no userData yet
    return t;
  }

  var guests = {}, count = 0;
  function Ghost(row) {
    var f = this;
    f.id = row[0]; f.color = (row[1] | 0) % PALETTE.length; f.cc = row[2] || '';
    f.x = f.tx = +row[3]; f.y = f.ty = +row[4]; f.z = f.tz = +row[5]; f.r = f.tr = +row[6];
    f.speed = 0; f.fade = 0; f.leaving = false;
    var sh = SHIFTS[(count++) % SHIFTS.length];
    f.u = { uColor: { value: new THREE.Color(PALETTE[f.color]) }, uGait: { value: 0 }, uPhase: { value: Math.random() * 6 },
      uFade: { value: 0 }, uShift: { value: new THREE.Vector2(sh[0], sh[1]) } };
    var uni = { uColor: f.u.uColor, uGait: f.u.uGait, uPhase: f.u.uPhase, uFade: f.u.uFade, uShift: f.u.uShift, uTime: U.time,
      uOpacity: U.opacity, uCell: U.cell, uKey: U.key, uKeyCol: U.keyCol, uFogCol: U.fogCol, uFogD: U.fogD };
    f.mat = new THREE.ShaderMaterial({ vertexShader: GHOST_VS, fragmentShader: GHOST_FS, uniforms: uni, side: THREE.DoubleSide,
      extensions: { derivatives: true } });
    f.eggMat = new THREE.ShaderMaterial({ vertexShader: EGG_VS, fragmentShader: EGG_FS, uniforms: uni });
    f.g = new THREE.Group(); f.body = new THREE.Group(); f.g.add(f.body);
    var m = new THREE.Mesh(geo, f.mat); m.raycast = noPick; f.body.add(m);
    var egg = new THREE.Mesh(EGG, f.eggMat); egg.raycast = noPick;
    egg.position.set(0, 1.62, 0.045); egg.scale.set(0.09, 0.105, 0.098); f.body.add(egg);
    var name = countryName(f.cc);
    if (name) {
      f.labMat = new THREE.SpriteMaterial({ map: labelTexture(name), transparent: true, depthWrite: false, toneMapped: false, fog: false });
      f.lab = new THREE.Sprite(f.labMat); f.lab.raycast = noPick; f.lab.renderOrder = 5; f.lab.center.set(0.5, 0); f.g.add(f.lab);
      f.name = name;
    }
    f.place();
    window.__scene.add(f.g);
  }
  Ghost.prototype.place = function () {
    this.g.position.set(this.x, this.y, this.z);
    this.g.rotation.y = this.r + Math.PI;      // the camera looks down -z, the figure's front is +z
  };
  Ghost.prototype.drop = function () {
    window.__scene.remove(this.g);
    this.mat.dispose(); this.eggMat.dispose();
    if (this.labMat) { this.labMat.map.dispose(); this.labMat.dispose(); }
  };
  function relabel() {
    for (var id in guests) {
      var f = guests[id];
      if (f.labMat) { f.labMat.map.dispose(); f.labMat.map = labelTexture(f.name); f.labMat.needsUpdate = true; }
    }
  }
  if (document.fonts && document.fonts.load) document.fonts.load('56px "DotGothic16"', 'ARMENIA').then(relabel, function () {});

  /* ---------- the line to the server ---------- */
  var ws = null, myId = null, mine = {}, retry = 0, retryTimer = 0, hiddenTimer = 0, paused = false;
  var sent = { x: 1e9, y: 0, z: 0, r: 0, at: 0 };
  function endpoint() {
    if (window.__hallsLive) return window.__hallsLive;
    var api = window.noeasy && window.noeasy.api;
    return api && /^https?:\/\//.test(api) ? api.replace(/^http/, 'ws').replace(/\/+$/, '') + '/api/halls/live' : '';
  }
  function clearGuests() {
    for (var id in guests) guests[id].leaving = true;
  }
  function connect() {
    clearTimeout(retryTimer);
    var url = endpoint();
    if (!url || ws || paused || !('WebSocket' in window)) return;
    /* after a dropped line the server may still hold this page's last figure: name it, so it goes at once */
    var prev = Object.keys(mine).pop();
    try { ws = new WebSocket(url + (prev ? '?prev=' + prev : '')); } catch (e) { ws = null; later(); return; }
    ws.onmessage = function (e) {
      var o; try { o = JSON.parse(e.data); } catch (x) { return; }
      if (!o) return;
      if (o.t === 'hi') { myId = o.id; mine[o.id] = 1; retry = 0; sent.x = 1e9; return; }
      if (o.t === 'all') { (o.v || []).forEach(add); return; }
      if (o.t === 'j') { add(o.v); return; }
      if (o.t === 'm') {
        (o.v || []).forEach(function (r) {
          var f = guests[r[0]]; if (!f || f.leaving) return;
          f.tx = +r[1]; f.ty = +r[2]; f.tz = +r[3]; f.tr = +r[4];
        });
        return;
      }
      if (o.t === 'l' && guests[o.id]) guests[o.id].leaving = true;
    };
    ws.onclose = function () { ws = null; myId = null; clearGuests(); later(); };
    ws.onerror = function () {};
  }
  function later() {
    if (paused) return;
    var wait = Math.min(30000, 1500 * Math.pow(2, retry++)) * (0.75 + Math.random() * 0.5);
    retryTimer = setTimeout(connect, wait);
  }
  function add(row) {
    if (!row || mine[row[0]] || !isFinite(+row[3]) || !isFinite(+row[5])) return;
    var f = guests[row[0]];
    if (f) { f.leaving = false; f.tx = +row[3]; f.ty = +row[4]; f.tz = +row[5]; f.tr = +row[6]; return; }
    if (Object.keys(guests).length >= 80) return;
    try { guests[row[0]] = new Ghost(row); } catch (e) { stop(e); }
  }
  /* a tab in the background stops being a statue in other people's hall after half a minute */
  document.addEventListener('visibilitychange', function () {
    clearTimeout(hiddenTimer);
    if (document.hidden) {
      hiddenTimer = setTimeout(function () { paused = true; clearTimeout(retryTimer); if (ws) ws.close(); }, 30000);
    } else if (paused) { paused = false; retry = 0; connect(); }
  });

  /* ---------- once a frame, from the hall's own loop ---------- */
  function angle(a) { return Math.atan2(Math.sin(a), Math.cos(a)); }
  var cam = new THREE.Vector3(), lp = new THREE.Vector3(), buf = new THREE.Vector2();
  function tick(dt, groundY, yaw) {
    if (!window.__started || !window.__scene || !window.__camera) return;
    if (!ws && !retryTimer && !paused) connect();
    var R = window.__renderer;
    if (R) U.cell.value = Math.max(2, Math.round(2 * R.getPixelRatio()));
    U.time.value += dt;
    var now = performance.now(), C = window.__camera;
    if (ws && ws.readyState === 1 && myId && isFinite(groundY)) {
      var x = C.position.x, z = C.position.z, moved = Math.hypot(x - sent.x, z - sent.z) > 0.03 || Math.abs(groundY - sent.y) > 0.05 ||
        Math.abs(angle(yaw - sent.r)) > 0.04;
      if (now - sent.at > SEND_EVERY && (moved || now - sent.at > IDLE_SEND)) {
        sent = { x: x, y: groundY, z: z, r: yaw, at: now };
        try { ws.send(JSON.stringify({ t: 'p', x: +x.toFixed(2), y: +groundY.toFixed(2), z: +z.toFixed(2), r: +angle(yaw).toFixed(2) })); } catch (e) {}
      }
    }
    var k = 1 - Math.exp(-dt / 0.12);
    C.getWorldPosition(cam);
    var bufH = R ? R.getDrawingBufferSize(buf).y : innerHeight;
    for (var id in guests) {
      var f = guests[id];
      if (Math.hypot(f.tx - f.x, f.tz - f.z) > 5 || Math.abs(f.ty - f.y) > 3) { f.x = f.tx; f.y = f.ty; f.z = f.tz; }   // a jump, not a walk
      var px = f.x, pz = f.z;
      f.x += (f.tx - f.x) * k; f.y += (f.ty - f.y) * k; f.z += (f.tz - f.z) * k;
      f.r += angle(f.tr - f.r) * k;
      var step = Math.hypot(f.x - px, f.z - pz);
      f.speed += (step / Math.max(dt, 1e-3) - f.speed) * Math.min(1, dt * 6);
      var gait = Math.min(1, f.speed / 1.8);
      f.u.uGait.value = gait;
      f.u.uPhase.value += step / STEP_LEN * Math.PI;
      var ph = f.u.uPhase.value;
      f.body.position.y = gait * 0.014 * (0.5 - 0.5 * Math.cos(2 * ph));
      f.body.rotation.set(gait * 0.035, gait * 0.04 * Math.sin(ph), gait * 0.02 * Math.sin(ph));
      f.fade = Math.max(0, Math.min(1, f.fade + (f.leaving ? -dt : dt) / 0.8));   // dots gather in, and thin out on leaving
      f.u.uFade.value = f.fade;
      f.place();
      if (f.lab) {
        f.lab.position.set(0, 1.9 + f.body.position.y, 0);             // its bottom edge, just over the hood
        f.lab.getWorldPosition(lp).applyMatrix4(C.matrixWorldInverse);
        var depth = Math.max(0.3, -lp.z), h = LABEL_PX / bufH * 2 * Math.tan(C.fov * Math.PI / 360) * depth;
        f.lab.scale.set(h * f.labMat.map.noeasyAspect, h, 1);
        f.labMat.opacity = 0.9 * f.fade;
      }
      if (f.leaving && f.fade <= 0) { f.drop(); delete guests[id]; }
    }
  }
  /* the hall's loop calls this every frame: whatever goes wrong here must never stop the hall itself,
     so the first error switches presence off for this visit and leaves the hall as it was */
  var dead = false;
  function stop(e) {
    if (dead) return;
    dead = true; paused = true;
    try { console.warn('[presence] switched off:', e); } catch (x) {}
    clearTimeout(retryTimer);
    try { if (ws) ws.close(); } catch (x) {}
    try { for (var id in guests) { guests[id].drop(); delete guests[id]; } } catch (x) {}
  }
  function safeTick(dt, groundY, yaw) {
    if (dead) return;
    try { tick(dt, groundY, yaw); } catch (e) { stop(e); }
  }
  safeTick.guests = guests;
  window.__presence = safeTick;
})();
